通常的做法1：js定时器由于这次做的是钉钉工作台自定义组件，钉钉不建议使用定时器，会影响性能
2：css3 动画实现css3动画流畅不卡顿。需要解决3个问题：1：循环滚动，且最后一条滚动完之后紧接着第一条出现2：滚动速度可调3：内容没有超过滚动区时，不需要滚动

要实现的效果图如下图所示：
对于循环滚动，如果按照一般做法，是没有办法做到 最后一条滚动完之后紧接着第一条出现的，那么怎么办呢？再复制一个滚动列表就可以了，第一个列表开始滚动时，第二个列表延时滚动，滚动速度一样，这样当第一个列表滚动完以后，第二个列表就会紧接着出现了。对于滚动的速度，因为滚动的宽度是不定的，是根据接口返回的内容决定的，但是 对于animation动画来说，宽度是一定的，改变整个动画的时间即可达到变速的效果，需要使用钉钉的查看元素的信息api去获取各个元素的宽度，动态设置速度。下面是关键代码 
// jsmethods: &#123;     async dealData() &#123;      let _sysInfo = await getSdk().getSystemInfo() || &#123;&#125;;      let &#123; windowWidth &#125; = _sysInfo;      let rpxToPxRatio = windowWidth / 750;      let &#123; widthControl, marqueeLogic, marqueeSpeed &#125; = this.props.componentProps;      // 需要先将列表的最大宽度设置为屏幕的宽度      this.setData(&#123;        listWidth: `--listMaxWidth: $&#123;windowWidth&#125;px;`      &#125;)      const query = my.createSelectorQuery();      query        .selectAll(`.marquee-notice .content`)        .boundingClientRect()        .selectAll(`.marquee-notice .list-group .list`)        .boundingClientRect()        .selectAll(`.marquee-notice .content-left`)        .boundingClientRect()        .exec(res =&gt; &#123;          console.error(res);          let contentWidth = res[0][0].width;          let _arr = res[1];          let _width = 0;          let plusWidth = res[2][0].width; // plusWidth表示每一行滚动的总距离          for (let i = 0; i &lt; _arr.length; i++) &#123;            _width += (_arr[i].width)          &#125;          let $_width = _width * 2 - plusWidth &gt;= contentWidth ? _width * 2 - plusWidth : contentWidth;          let speed = $_width &gt;= (contentWidth * 2) ? (0.0187) : (0.0187 * 2); // 如果总的列表宽度大于等于 content 宽度的两倍（因为是两个列表动画）则使用3 / 161速率，否则使用6 / 161 。速度不能百分比准确          let groupStyle_1 = &#x27;&#x27;;          let groupStyle_2 = &#x27;&#x27;;          console.error(&#x27;list宽度和content宽度&#x27;, _width, contentWidth)          if (marqueeLogic === 1 || marqueeLogic === 2 &amp;&amp; (_width + 10) &gt; contentWidth) &#123;            // 无论是否超过内容宽度，都滚动            groupStyle_1 = `              animation: run $&#123;$_width * (speed / marqueeSpeed)&#125;s linear 0s infinite;              --width:$&#123;-(parseInt($_width))&#125;px;              --leftPosition: $&#123;plusWidth&#125;px;            `;            groupStyle_2 = `              animation: run2 $&#123;$_width * (speed / marqueeSpeed)&#125;s linear $&#123;$_width * (speed / marqueeSpeed) / 2&#125;s infinite;              --width:$&#123;-(parseInt($_width))&#125;px;              --leftPosition: $&#123;plusWidth&#125;px;                      `;          &#125; else &#123;            // 只有超过content宽度才滚动            groupStyle_1 = &#x27;transform: translateX(0);&#x27;;          &#125;          this.setData(&#123;            groupStyle_1: groupStyle_1,            groupStyle_2: groupStyle_2,          &#125;)        &#125;);    &#125;,&#125;
// css 关键代码：.list-group-2 &#123;    display: flex;    position: absolute;    width: 100%;    // animation: run2 linear 24s infinite;    // animation-delay:12s; 因为变量是通过js查询的，存在异步，所以只能写行内样式    transform: translateX(var(--leftPosition, 375px));&#125;// 第一行滚动文本@keyframes run &#123;    0% &#123;    transform: translateX(var(--leftPosition, 375px));    opacity: 1;    &#125;    1% &#123;    opacity: 1;    &#125;    99% &#123;    opacity: 1;    &#125;    100% &#123;    transform: translateX(var(--width, -600px));    opacity: 0;    &#125;&#125;// 第二行滚动文本@keyframes run2 &#123;    0% &#123;    transform: translateX(var(--leftPosition, 375px));    &#125;    1% &#123;    opacity: 1;    &#125;    99% &#123;    opacity: 1;    &#125;    100% &#123;    transform: translateX(var(--width, -600px));    &#125;&#125;
// axml&lt;view class=&quot;content&quot; style=&quot;&#123;&#123;listWidth&#125;&#125;&quot;&gt;    &lt;view class=&quot;list-group&quot;  style=&quot;&#123;&#123;groupStyle_1&#125;&#125;&quot;&gt;    &lt;block a:for=&quot;&#123;&#123;list&#125;&#125;&quot; a:key=&quot;&#123;&#123;i&#125;&#125;&quot; a:for-index=&quot;i&quot;&gt;        &lt;view class=&quot;list &#123;&#123;componentProps.widthControl === 1 ? &#x27;max-width&#x27; : &#x27;&#x27;&#125;&#125;&quot; onTap=&quot;handleTapLink&quot; data-url=&quot;&#123;&#123;item.link&#125;&#125;&quot;&gt;        &lt;view class=&quot;list-text&quot;&gt;&#123;&#123;item.title&#125;&#125;&lt;/view&gt;        &lt;/view&gt;    &lt;/block&gt;    &lt;/view&gt;    &lt;view class=&quot;list-group-2&quot;  style=&quot;&#123;&#123;groupStyle_2&#125;&#125;&quot;&gt;    &lt;block a:for=&quot;&#123;&#123;list&#125;&#125;&quot; a:key=&quot;&#123;&#123;i&#125;&#125;&quot; a:for-index=&quot;i&quot;&gt;        &lt;view class=&quot;list &#123;&#123;componentProps.widthControl === 1 ? &#x27;max-width&#x27; : &#x27;&#x27;&#125;&#125;&quot; onTap=&quot;handleTapLink&quot; data-url=&quot;&#123;&#123;item.link&#125;&#125;&quot; style=&quot;&#123;&#123;componentProps.widthControl === 1 ? &#x27;max-width: var(--listMaxWidth, 4rem)&#x27;:&#x27;&#x27;&#125;&#125;&quot;&gt;        &lt;view class=&quot;list-text&quot;&gt;&#123;&#123;item.title&#125;&#125;&lt;/view&gt;        &lt;/view&gt;    &lt;/block&gt;    &lt;/view&gt;&lt;/view&gt;

表格中的input需要做某些校验，比如，“本次报销金额”要小于“未报销金额”，这就有点麻烦了，我们都知道，element的form的验证规则rules都是在初始化的时候就定好了的，比如时间验证：
date2: [    &#123; type: &#x27;date&#x27;, required: true, message: &#x27;请选择时间&#x27;, trigger: &#x27;change&#x27; &#125;],
而我们项目中的是这样的: 又不想自定义指令来做，还是看下element能不能做吧，于是就开始看文档，发现只能用自定义rules，但是自定义指令，写死的规则也不符合要求啊，因为表格的数据都是不固定的，首先我们把表格的数据源字段移到我们的form中然后自定义规则：这里需要用到一些技巧，比如在模板中，
:prop=&quot;`inputTaxTable.$&#123;scope.$index&#125;.thisApplyMoney`&quot;
在需要校验的列中，inputTaxTable.$&#123;scope.$index&#125;.thisApplyMoney 查找当前行的数据源，
以及查找“未报销金额”这行的数据来跟当前金额进行对比的时候，保证找到的当前行的数据。
 //field字段中包含了该行表格的index    let field=rule.field;//规则名称    let _fieldArr=[];    _fieldArr=field.split(&#x27;.&#x27;);    let _index=_fieldArr[1];//得到表格的第n行    if(Number.parseFloat(value)&gt;Number.parseFloat(this.ruleForm.inputTaxTable[_index].notApplyMoney))&#123;        return callback(new Error(&#x27;不可大于未报销金额&#x27;));    &#125;else&#123;        callback()  //这里一定要这样返回，否则validate函数只会执行一次    &#125;    &#125;

koa2 上传文件
本来是使用 koa-body 这个包来接收上传文件的，这个包也可以读取get请求，本来以为直接用它来接收文件及其他请求，把koa-bodyparser去掉，但是后来发现koa-body 接收post请求时报415，不支持的媒体类型错误，然后一时也 找不出原因，就干脆不用这个包了，接收正常的请求还是使用koa-bodyparser，然后文件上传接收用@koa/multer。
@koa/multer不是一个中间件，因此不能像其他中间件一样直接在app.js中引入，使用的方式如下：
// 前端路由const router = require(&#x27;koa-router&#x27;)();const path = require(&#x27;path&#x27;)router.prefix(&#x27;/api&#x27;); //路由前缀const multer = require(&#x27;@koa/multer&#x27;);// 上传配置const storage = multer.diskStorage(&#123;  destination: function (req, file, cb) &#123;    cb(null, path.join(__dirname, &#x27;../../public/upload/&#x27;));  &#125;,  filename: function (req, file, cb) &#123;    cb(null, file.fieldname + &#x27;-&#x27; + Date.now() + &#x27;.png&#x27;)  &#125;&#125;)const upload = multer(&#123; storage: storage &#125;)// 使用multer上传router.post(&#x27;/tv/upload_channel_poster&#x27;, upload.single(&#x27;file&#x27;), Tv.updateChannelPoster)

前言vue早就有成熟的vue-cli工具了，现在是vue-cli 3.0了，但是觉得很有必要自己去实现一下，有助于自己技术的提高，也能更好地去了解webpack。本人是webpack菜鸟，有些资料是网上学习整理过来的。


1.新建目录文件夹第一步当然是新建工程目录了，具体怎么建就随便了，比如我建立webpackVue这个目录
2.新建package.json文件package.json是nodejs项目必需的配置文件。使用npm init,按照提示一步步填写项目名称，作者等信息
3.webpack配置新建build文件夹build目录下新建webpack.base.conf.js,webpack.dev.conf.js,webpack.prod.conf.js文件，webpack.base.conf.js是公共基础配置，webpack.dev.conf.js是生产环境配置文件，webpack.prod.conf.js是生产环境配置。创建一个src目录，用来存放我们的项目源文件，然后创建main.js文件，创建一个index.html
&lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt;    &lt;meta charset=&quot;UTF-8&quot;&gt;    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;    &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt;    &lt;title&gt;webpack4搭建vue&lt;/title&gt;&lt;/head&gt;&lt;body&gt;    &lt;div id=&quot;app&quot;&gt;&lt;/div&gt;&lt;/body&gt;&lt;/html&gt;
 目录结构是这样的
下载webpack webpack-dev-server webpack-cli (这里webpack是局部安装)npm i webpack webpack-dev-server webpack-cli -D打开webpack.base.config.js，逐步添加配置
var path = require(&#x27;path&#x27;);var webpack = require(&#x27;webpack&#x27;);module.exports =&#123;    //入口文件    entry:&#123;        main: path.resolve(__dirname, &#x27;../src/main.js&#x27;)    &#125;,    //输出目录    output:&#123;        path: path.resolve(__dirname, &#x27;../dist&#x27;),        filename: &#x27;[name].[hash].js&#x27;    &#125;,    module:&#123;        rules:[]    &#125;,    plugins:[        new webpack.HashedModuleIdsPlugin(), // 解决vender后面的hash每次都改变    ],    resolve:&#123;    &#125;&#125;
4.配置loader配置babel编译代码：下载babel-loader，babel-core，babel-preset-dev。npm i babel-loader babel-core babel-preset-env -D
babel-preset-env 帮助我们配置 babel。我们只需要告诉它我们要兼容的情况（目标运行环境），它就会自动把代码转换为兼容对应环境的代码。babel-core是作为babel的核心存在，babel的核心api都在这个模块里面这里有个注意的地方，就是babel的版本的问题，运行的时候根据提示安装合适的版本就好了，这里不记得是babel的哪个工具需要7的版本了。在webpack.base.conf.js文件中增加babel配置
rules:[    &#123;        test: /\.js$/, //匹配.js结尾的文件        use: [&#x27;babel-loader&#x27;],        exclude:/node_modules/ //排除node_modules里面的js    &#125;,]
新建.babelrc文件，.babelrc是babel全局配置文件
&#123;    &quot;presets&quot;:[        [&quot;env&quot;,&#123;            &quot;targets&quot;: &#123;                    &quot;browsers&quot;: [&quot;&gt; 1%&quot;, &quot;last 2 versions&quot;, &quot;not ie &lt;=8&quot;],                //&quot;chrome&quot;: 52,                //&quot;browsers&quot;: [&quot;last 2 versions&quot;, &quot;safari 7&quot;]            &#125;,                   &quot;modules&quot;: false        &#125;]    ]&#125;
下载file-loadernpm i file-loader -D继续追加配置
rules:[    &#123;        test: /\.(jpg|png|svg|gif)$/,        use:[&#x27;file-loader&#x27;]    &#125;,    &#123;        test:/\.(woff|woff2|eot|ttf|otf)$/    &#125;,]
下载css-loader，vue-style-loader，sass-loader， node-sass，less，less-loader并配置css，scss，sass,lessnpm i css-loader vue-style-loader sass-loader node-sass less-loader less -D
rules:[    &#123;        test:/\.(sa|sc|c)ss$/,        use:[            &#123;                loader: &#x27;vue-style-loader&#x27;            &#125;,            &#x27;css-loader&#x27;,            &#x27;sass-loader&#x27;        ]    &#125;,    &#123;        test:/\.less$/,        use:[            &#123;                loader: &#x27;vue-style-loader&#x27;            &#125;,            &#x27;css-loader&#x27;,            &#x27;sass-loader&#x27;        ]    &#125;,]
5.处理html文件下载html-webpack-pluginnpm i html-webpack-plugin -D
var HtmlWebpackPlugin = require(&#x27;html-webpack-plugin&#x27;); //在base配置文件头部引入new HtmlWebpackPlugin(&#123;    template: path.resolve(__dirname, &#x27;../index.html&#x27;)&#125;),
6.解析模块的配置和配置别名resolve: &#123;    // 能够使用户在引入模块时不带扩展    extensions: [&#x27;.js&#x27;, &#x27;.json&#x27;, &#x27;.vue&#x27;, &#x27;css&#x27;],    //别名    alias: &#123;        &#x27;vue$&#x27;:&#x27;vue/dist/vue.esm.js&#x27;,        &#x27;@&#x27;: path.resolve(__dirname, &#x27;../src&#x27;)    &#125;    &#125;
7.配置webpack.dev.conf.js文件下载 webpack-merge，用于合并配置npm i webpack-merge -D
var merge = require(&#x27;webpack-merge&#x27;);var baseConfig = require(&#x27;./webpack.base.conf&#x27;);var path = require(&#x27;path&#x27;);var webpack = require(&#x27;webpack&#x27;);module.exports = merge(baseConfig, &#123;    devtool: &#x27;inline-source-map&#x27;, // 压缩方式    mode: &#x27;development&#x27;,    devServer: &#123;        hot: true, // 热更新        open: true, // 自动打开页面        contentBase: path.resolve(__dirname, &#x27;../src&#x27;), // 告诉服务从哪提供内容    &#125;,    plugins: [        new webpack.HotModuleReplacementPlugin(), //开启热更新    ]&#125;)
8.配置webpack.prod.conf.jsvar merge = require(&#x27;webpack-merge&#x27;);var baseConfig = require(&#x27;./webpack.base.conf&#x27;);var path = require(&#x27;path&#x27;);var webpack = require(&#x27;webpack&#x27;);module.exports = merge(baseConfig, &#123;    devtool: &#x27;source-map&#x27;, // 压缩方式    mode: &#x27;production&#x27;,    plugins: [    ]&#125;)
9.配置vue-loader首先要下载vue，以及vue相关的模块npm i vue vue-loader vue-template-compiler -D继续完善webpack.base.cond.js
var VueLoaderPlugin=require(&#x27;vue-loader/lib/plugin&#x27;);//省略部分代码...rules:[    &#123;        test: /\.vue$/,        use: [&#x27;vue-loader&#x27;],        exclude: /node_modules/    &#125;,]//省略部分代码...plugins:[    new VueLoaderPlugin(), // 它的职责是将你定义过的其它规则复制并应用到 .vue 文件里相应语言的块]
在src目录新建app.vue文件和main.js文件
//app.vue&lt;template&gt;    &lt;div&gt;&#123;&#123;str&#125;&#125;&lt;/div&gt;&lt;/template&gt;&lt;script&gt;  export default &#123;    name: &#x27;App&#x27;,    data () &#123;      return &#123;        str: &#x27;欢迎来到自定义webpack4+vue构建&#x27;      &#125;    &#125;  &#125;&lt;/script&gt;&lt;style lang=&quot;scss&quot;&gt;  div &#123;    color: red;  &#125;&lt;/style&gt;
//main.jsimport Vue from &#x27;vue&#x27;import App from &#x27;./App&#x27;new Vue(&#123;    el: &quot;#app&quot;,    render: (h) =&gt; h(App)&#125;)
10.配置命令打开package.json文件，并配置开发和打包命令
// 省略代码。。。&quot;scripts&quot;: &#123;  &quot;dev&quot;: &quot;webpack-dev-server  --progress --config build/webpack.dev.conf.js&quot;,   &quot;build&quot;: &quot;webpack --config build/webpack.prod.conf.js&quot;  &#125;
npm run dev 就可以启动项目了
继续优化…11. 区分环境引入不同地址新建config文件夹并新建dev.env.js和prod.env.js
//dev.env.js 开发环境配置&#x27;use strict&#x27;module.exports = &#123;    NODE_ENV: &quot;development&quot;,    BASE_API: &quot;http://1456&quot;,&#125;

