//webpack.prod.conf.jsconst MiniCssExtractPlugin = require(&#x27;mini-css-extract-plugin&#x27;);module: &#123;    rules: [        &#123;            test: /\.(c|sc|sa)ss$/,            use: [                &#123;                loader: MiniCssExtractPlugin.loader,                &#125;,                &#x27;css-loader&#x27;,                &#x27;sass-loader&#x27;            ]        &#125;,        &#123;        test: /\.less$/,        use: [            &#123;            loader: MiniCssExtractPlugin.loader,            &#125;,            &#x27;css-loader&#x27;,            &#x27;less-loader&#x27;            ]        &#125;    ]&#125;,plugins: [    new MiniCssExtractPlugin(&#123;        filename: &#x27;[name].[hash].css&#x27;    &#125;)]
