在js中经常需要用到变量的拷贝，比如var a=1;var b=a; 这个时候修改b的值，a不会改变b=2;console.log(a); //1,但是需要注意，这种方式拷贝属于浅拷贝，只局限在简单类型的拷贝：string、number、boolean、null、undefiend。如果你用这种方式拷贝一个数组或者对象，那么就得注意了，

var a=[1,2,3]; var b=a;b[0]=66;console.log(a); //[66,2,3];
可以看到，b的值变了，a也变了，所以对于数组和对象不能用这种浅拷贝，因为拷贝的只是引用地址，实际上还是同一个，不过在有一种情况下，修改复制后的变量，被复制的变量不会跟着改变，那就是复制后，给复制变量重新定义值得时候，原来的变量不会受影响，因为此时已经给复制后的变量重新分配指针了，如下面所示：
var arr = [1,2,3,4];var arr_copy = arr ;arr_copy = [1,2,3,4,5];console.log(arr); //[1,2,3,4]console.log(arr_copy);//[1,2,3,4,5]var obj = &#123;    name:&#x27;张三&#x27;,    age:20&#125;;var obj_copy = obj ;obj_copy = &#123;    name:&#x27;李四&#x27;,    age:20&#125;;console.log(obj.name);//张三console.log(obj_copy.name);//李四

使用递归进行深拷贝。var car = &#123;    name : &#x27;宝马&#x27;,    color:&#x27;红色&#x27;,&#125;//判断是数组还是对象function getType(obj)&#123;    if(Object.prototype.toString.call(obj)==&#x27;[object Object]&#x27;)&#123;        return &#x27;Object&#x27;;    &#125;else if(Object.prototype.toString.call(obj)==&#x27;[object Array]&#x27;)&#123;        return &#x27;Array&#x27;;    &#125;else&#123;        return &#x27;nomal&#x27;;    &#125;&#125;function deepCopy(obj) &#123;    if (getType(obj)==&#x27;nomal&#x27;) &#123;        return obj ;  //如果是基本类型则直接返回    &#125;else&#123;        var newObj = getType(obj)==&#x27;Object&#x27;?&#123;&#125;:[];        for(var key in obj)&#123;            if(obj.hasOwnProperty(key))&#123;                newObj[key] = deepCopy(obj[key]); //递归            &#125;        &#125;    &#125;    return newObj;&#125;var newCar = deepCopy(car) ;newInfo.name = &#x27;奔驰&#x27;;console.log(newCar); //&#123;name:&#x27;奔驰&#x27;,color:&#x27;红色&#x27;&#125;console.log(car);//&#123;name:&#x27;宝马&#x27;,color:&#x27;红色&#x27;&#125;
这里用到.hasOwnProperty是为了避免在有继承时拷贝到继承自对象中的值（也就是a继承b时,使用.hasOwnProperty就是为了只拷贝a中的变量，过滤继承自b中的变量）

